<?php
namespace App\Services;
use Illuminate\Support\Str;
class SupplierNormalizer { public function normalizeDocument(?string $v):?string{$v=preg_replace('/\D/','',(string)$v);return $v?:null;} public function detectDocumentType(?string $v):?string{$n=$this->normalizeDocument($v);return strlen((string)$n)===11?'cpf':(strlen((string)$n)===14?'cnpj':null);} public function formatDocument(?string $v):?string{$v=$this->normalizeDocument($v);if(!$v)return null;return strlen($v)===14?preg_replace('/^(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})$/','$1.$2.$3/$4-$5',$v):(strlen($v)===11?preg_replace('/^(\d{3})(\d{3})(\d{3})(\d{2})$/','$1.$2.$3-$4',$v):$v);} public function validDocument(?string $v):bool{$type=$this->detectDocumentType($v);return $type==='cpf'?$this->validateCpf($v):($type==='cnpj'?$this->validateCnpj($v):false);} public function validateCpf(?string $v):bool{$v=$this->normalizeDocument($v);if(strlen((string)$v)!==11||preg_match('/^(\d)\1+$/',$v))return false;for($p=9;$p<11;$p++){ $sum=0;for($i=0;$i<$p;$i++)$sum+=(int)$v[$i]*(($p+1)-$i);$d=(($sum*10)%11)%10;if($d!=(int)$v[$p])return false;}return true;} public function validateCnpj(?string $v):bool{$v=$this->normalizeDocument($v);if(strlen((string)$v)!==14||preg_match('/^(\d)\1+$/',$v))return false;foreach([12,13] as $p){$sum=0;$weight=$p===12?5:6;for($i=0;$i<$p;$i++){$sum+=(int)$v[$i]*$weight;if(--$weight<2)$weight=9;}$d=$sum%11<2?0:11-($sum%11);if($d!=(int)$v[$p])return false;}return true;} public function normalizeName(?string $v):string{$v=Str::ascii(Str::lower(trim((string)$v)));$v=preg_replace('/\b(ltda|me|epp|s\/?a)\b\.?/','',$v);return trim(preg_replace('/\s+/',' ',preg_replace('/[^a-z0-9\s]/',' ',$v)));} public function searchTokens(?string $v):array{$tokens=explode(' ',$this->normalizeName($v));return array_values(array_filter($tokens,fn($x)=>!in_array($x,['da','de','do','das','dos'],true)));} }
